/* 大小写不敏感的前 n 个宽字符比较（ASCII 关键字） */
static int b3_ci_cmp(const WCHAR *s, const WCHAR *t, int n)
{
    int i;
    for (i = 0; i < n; i++) {
        uint16_t x = (uint16_t)(s[i] | 0x20);
        uint16_t y = (uint16_t)(t[i] | 0x20);
        if (x != y) return 1;
    }
    return 0;
}

/* Ghidra 将 64 位返回寄存器视为 POINT (低32位 x, 高32位 y) */
static POINT b3_po_from_u64(uint64_t v)
{
    POINT p;
    p.x = (LONG)(uint32_t)v;
    p.y = (LONG)(uint32_t)(v >> 32);
    return p;
}

/* IEEE754 double <-> uint64 位模式互转 (FUN_140070da8 计算器位运算需直接操纵 double 位) */
static uint64_t b3_d2u(double d) { uint64_t u; memcpy(&u, &d, 8); return u; }
static double  b3_u2d(uint64_t u) { double d; memcpy(&d, &u, 8); return d; }

